drop policy if exists "Users update own profile" on public.profiles;revoke update on public.profiles from authenticated;grant update(username) on public.profiles to authenticated;create policy "Users update own username" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists "Authenticated submit places" on public.places;drop policy if exists "Owners or curators update places" on public.places;drop policy if exists "Authenticated create places" on public.places;drop policy if exists "Place owner updates" on public.places;
create policy "Contributors insert pending" on public.places for insert to authenticated with check(owner_id=auth.uid() and status='pending' and is_point_verified=false and is_assortment_verified=false and closed_reports_count=0);
create policy "Owners update own places" on public.places for update to authenticated using(owner_id=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='owner')) with check(owner_id=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='owner'));
create policy "Curators update places" on public.places for update to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='curator')) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='curator'));
create function public.guard_place_trust() returns trigger language plpgsql security definer set search_path='' as $$declare r text;begin select role into r from public.profiles where id=auth.uid();if r<>'curator' and current_setting('second_chance.rpc_trust_update',true) is distinct from 'on' and (new.is_point_verified is distinct from old.is_point_verified or new.is_assortment_verified is distinct from old.is_assortment_verified or new.closed_reports_count is distinct from old.closed_reports_count or new.status is distinct from old.status) then raise exception 'Trust/status fields restricted';end if;return new;end;$$;create trigger guard_place_trust before update on public.places for each row execute function public.guard_place_trust();
drop policy if exists "Authenticated submit reviews" on public.reviews;drop policy if exists "Reviews insert by author" on public.reviews;create policy "Review insert author only" on public.reviews for insert to authenticated with check(author_id=auth.uid());
drop policy if exists "Authenticated submit finds" on public.finds;drop policy if exists "Finds insert by author" on public.finds;create policy "Find insert author only" on public.finds for insert to authenticated with check(author_id=auth.uid());
update storage.buckets set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp','image/gif'] where id='finds-photos';
drop policy if exists "Authenticated upload finds photos" on storage.objects;drop policy if exists "Auth photo upload" on storage.objects;create policy "Auth photo upload" on storage.objects for insert to authenticated with check(bucket_id='finds-photos' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.confirm_place_status(place_uuid uuid,is_closed boolean) returns jsonb language plpgsql security definer set search_path='' as $$declare u uuid;begin perform set_config('second_chance.rpc_trust_update','on',true);if is_closed then update public.places set closed_reports_count=closed_reports_count+1,status=case when closed_reports_count+1>=3 then 'questionable' else status end,updated_at=now() where id=place_uuid and status<>'closed' returning id into u;else update public.places set last_confirmed_at=now(),updated_at=now() where id=place_uuid and status<>'closed' returning id into u;end if;return jsonb_build_object('ok',u is not null,'place_id',u);end;$$;revoke all on function public.confirm_place_status(uuid,boolean) from public;grant execute on function public.confirm_place_status(uuid,boolean) to anon,authenticated;